package net.officefloor.hq.app.statement;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;

/** A statement taken for a person: their due-total then (none when it was n/a), how many of their claims
 * counted, and the sheet's today when it was taken. */
@Entity
@Table(name = "statement")
public class Statement {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    @Column(name = "taken_on", nullable = false)
    private LocalDate takenOn;

    @Column(name = "taken_by", nullable = false)
    private String takenBy;

    @Column(name = "due_total", precision = 14, scale = 2)
    private BigDecimal dueTotal;

    @Column(name = "claims", nullable = false)
    private int claims;

    protected Statement() {}

    public Statement(String sheetId, Long personId, LocalDate takenOn, String takenBy, BigDecimal dueTotal,
            int claims) {
        this.sheetId = sheetId;
        this.personId = personId;
        this.takenOn = takenOn;
        this.takenBy = takenBy;
        this.dueTotal = dueTotal;
        this.claims = claims;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public Long getPersonId() {
        return personId;
    }

    public LocalDate getTakenOn() {
        return takenOn;
    }

    public String getTakenBy() {
        return takenBy;
    }

    public BigDecimal getDueTotal() {
        return dueTotal;
    }

    public int getClaims() {
        return claims;
    }
}
package net.officefloor.hq.app.statement;

import java.util.List;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;

public interface StatementRepository extends JpaRepository<Statement, Long> {

    /** The sheet's statements in the order they were taken. */
    List<Statement> findBySheetIdOrderByIdAsc(String sheetId);

    /** The person's last statement, if any. */
    Optional<Statement> findFirstBySheetIdAndPersonIdOrderByIdDesc(String sheetId, Long personId);
}
package net.officefloor.hq.app.statement;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.rollup.RollupService.Snapshot;
import net.officefloor.hq.app.setting.SettingService;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class StatementService {

    /** What a person's statements come to: how many, and the last one (none before the first). */
    public record Summary(int count, Statement last) {}

    private final StatementRepository statements;
    private final ClaimRepository claims;
    private final ClaimService claimService;
    private final PersonRepository people;
    private final SheetService sheets;
    private final RollupService rollup;
    private final SettingService settings;
    private final Audit audit;

    public StatementService(StatementRepository statements, ClaimRepository claims, ClaimService claimService,
            PersonRepository people, SheetService sheets, RollupService rollup, SettingService settings, Audit audit) {
        this.statements = statements;
        this.claims = claims;
        this.claimService = claimService;
        this.people = people;
        this.sheets = sheets;
        this.rollup = rollup;
        this.settings = settings;
        this.audit = audit;
    }

    /** Each person's statements on the sheet, by person id. */
    @Transactional(readOnly = true)
    public Map<Long, Summary> summaries(String sheetId) {
        Map<Long, Summary> by = new HashMap<>();
        for (Statement s : statements.findBySheetIdOrderByIdAsc(sheetId)) {
            Summary was = by.get(s.getPersonId());
            by.put(s.getPersonId(), new Summary(was == null ? 1 : was.count() + 1, s));
        }
        return by;
    }

    /**
     * Take a statement for a person: record their due-total now, late charges included and held to the cap, and bind each of their
     * claims that counts (OPEN and PENDING ones within a hold, unbound, and deferred ones do not) to the figure it has now (never its late charge, which keeps following the sheet's
     * today); a claim of theirs that does not count is left unbound.
     */
    @Transactional
    public Person take(String user, String sheetId, Long personId) {
        LocalDate today = sheets.today(sheetId);
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
        Snapshot before = rollup.snapshot(sheetId);
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        boolean fixed = false;
        List<Claim> counted = new ArrayList<>();
        for (Claim claim : claims.findBySheetIdAndPersonId(sheetId, personId)) {
            if (!RollupService.counts(claim, person, today)) {
                claim.unbind();
                continue;
            }
            BigDecimal figure = claimService.figureOf(claim, person);
            BigDecimal due = rollup.dueOf(claim, person);
            fixed |= due != null;
            claim.bind(figure);
            counted.add(claim);
            if (due != null) {
                total = total.add(due);
            }
        }
        // Like the screen: with no rate in force today and no claim having a figure, the due-total is n/a.
        boolean rated = rollup.rated(person, counted, today);
        BigDecimal dueTotal = rollup.capped(sheetId, rated || fixed ? total : null);
        claims.flush();
        statements.saveAndFlush(new Statement(sheetId, personId, today, user, dueTotal, counted.size()));
        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + person.getName()
                + " due-total=" + (dueTotal != null ? dueTotal.toPlainString() : "n/a")
                + " claims=" + counted.size());
        rollup.recordChanges(user, sheetId, before);
        return person;
    }

    /**
     * A steward cancels a person's last statement: it is removed, and the claims it bound are live again (a figure
     * bound by the statement before it is not restored). Refused for anyone else, and for a person with no statement.
     */
    @Transactional
    public Person cancel(String user, String sheetId, Long personId) {
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
        settings.requireSteward(sheetId, user);
        Statement last = statements.findFirstBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
                        "That person has no statement to cancel."));
        Snapshot before = rollup.snapshot(sheetId);
        // Every claim of the person still bound was bound by their last statement, which rebinds or unbinds each.
        for (Claim claim : claims.findBySheetIdAndPersonId(sheetId, personId)) {
            if (claim.isStated()) {
                claim.unbind();
            }
        }
        claims.flush();
        statements.delete(last);
        statements.flush();
        audit.recordOnCommit("STATEMENT_CANCELLED sheet=" + sheetId + " by=" + user + " name=" + person.getName()
                + " due-total=" + (last.getDueTotal() != null ? last.getDueTotal().toPlainString() : "n/a"));
        rollup.recordChanges(user, sheetId, before);
        return person;
    }
}
package db.migration;

import java.sql.Connection;
import java.sql.ResultSet;
import java.sql.Statement;
import java.util.ArrayList;
import java.util.List;
import org.flywaydb.core.api.migration.BaseJavaMigration;
import org.flywaydb.core.api.migration.Context;

/**
 * A correction's amount is negative, so the claim table no longer requires an amount of 0.00 or more; it requires
 * instead that a negative amount names the claim it corrects. The old check was created unnamed, so it is found
 * by its table.
 */
public class V26__claim_amount_may_be_negative extends BaseJavaMigration {

    @Override
    public void migrate(Context context) throws Exception {
        Connection connection = context.getConnection();
        List<String> checks = new ArrayList<>();
        try (Statement statement = connection.createStatement();
                ResultSet rs = statement.executeQuery("SELECT tc.CONSTRAINT_NAME FROM INFORMATION_SCHEMA.TABLE_CONSTRAINTS tc"
                        + " JOIN INFORMATION_SCHEMA.CHECK_CONSTRAINTS cc ON cc.CONSTRAINT_SCHEMA = tc.CONSTRAINT_SCHEMA"
                        + " AND cc.CONSTRAINT_NAME = tc.CONSTRAINT_NAME"
                        + " WHERE tc.TABLE_NAME = 'CLAIM' AND tc.CONSTRAINT_TYPE = 'CHECK'"
                        + " AND UPPER(cc.CHECK_CLAUSE) LIKE '%AMOUNT%'")) {
            while (rs.next()) {
                checks.add(rs.getString(1));
            }
        }
        try (Statement statement = connection.createStatement()) {
            for (String check : checks) {
                statement.execute("ALTER TABLE claim DROP CONSTRAINT \"" + check + "\"");
            }
            statement.execute("ALTER TABLE claim ADD CONSTRAINT claim_correction_names_claim"
                    + " CHECK (amount >= 0 OR corrects IS NOT NULL)");
        }
    }
}
