248	                : datesByNumber.getOrDefault(claim.getCorrects(), claim.getDate());
249	    }
250	
251	    /** The dates of the claims given that have a number, by number. */
252	    private static Map<String, LocalDate> datesByNumber(List<Claim> given) {
253	        Map<String, LocalDate> by = new HashMap<>();
254	        for (Claim claim : given) {
255	            if (claim.getNumber() != null) {
256	                by.put(claim.getNumber(), claim.getDate());
257	            }
