269	
270	    private static boolean rated(Person person, List<Claim> counted, LocalDate today,
271	            Map<String, List<Rate>> byGrade) {
272	        if (today == null) {
273	            return false;
274	        }
275	        Set<String> grades = new HashSet<>();
