282	
283	    /** The rates of the grade the claim's person has on the claim's date. */
284	    private List<Rate> gradeRates(Claim claim, Person person) {
285	        return rates.findBySheetIdAndGrade(claim.getSheetId(), person.gradeOn(claim.getDate()));
286	    }
287	
288	    /** The rates of the grade a person has on a date. */
289	    private static List<Rate> ratesOn(Person person, LocalDate date, Map<String, List<Rate>> byGrade) {
290	        return byGrade.getOrDefault(person.gradeOn(date), List.of());
291	    }
292	
293	    /** The sheet's rates by grade. */
294	    private Map<String, List<Rate>> ratesByGrade(String sheetId) {
295	        Map<String, List<Rate>> by = new HashMap<>();
296	        for (Rate rate : rates.findBySheetId(sheetId)) {
297	            by.computeIfAbsent(rate.getGrade(), k -> new ArrayList<>()).add(rate);
298	        }
