303	        if (claim.getSettledDue() != null) {
304	            return claim.getSettledDue();
305	        }
306	        RoundingMode rounding = late.rounding(roundsBy);
307	        return floored(claim, figureOf(claim, gradeRates, rounding), claim.getStatus().isOpen(), late, rounding);
308	    }
