311	     * correction's is its figure alone (no floor, no charge); none when the figure is n/a. */
312	    private static BigDecimal floored(Claim claim, BigDecimal figure, boolean open, Lateness late,
313	            RoundingMode rounding) {
314	        if (figure == null || claim.isCorrection()) {
315	            return figure;
316	        }
317	        return figure.add(lateCharge(claim, open, figure, late, rounding)).max(late.floor(claim).setScale(2));
318	    }
