320	    /**
321	     * The late charge on a claim overdue (OPEN or PENDING, and its due-by, fixed when it was added, before the sheet's today):
322	     * for each full 30 days it is overdue, the late percent in force on that boundary date (its due-by plus 30, 60, 90 ... days)
323	     * of its figure, rounded to two decimals as the claim rounds, the charges added up; a boundary whose percent is 0.00 adds
324	     * nothing. A statement never binds it: it follows the sheet's today. A correction has none.
325	     */
326	    private static BigDecimal lateCharge(Claim claim, boolean open, BigDecimal figure, Lateness late,
327	            RoundingMode rounding) {
328	        BigDecimal charge = BigDecimal.ZERO.setScale(2);
329	        if (!open || late.today() == null || claim.isCorrection() || claim.deferredOn(late.today())) {
330	            return charge;
331	        }
332	        long overdueDays = ChronoUnit.DAYS.between(claim.getDueBy(), late.today());
333	        long periods = overdueDays > 0 ? overdueDays / LATE_PERIOD_DAYS : 0;
334	        for (long k = 1; k <= periods; k++) {
335	            BigDecimal pct = late.latePct(claim.getDueBy().plusDays(k * LATE_PERIOD_DAYS));
336	            if (pct.signum() != 0) {
337	                charge = charge.add(figure.multiply(pct).divide(BigDecimal.valueOf(100), 2, rounding));
338	            }
339	        }
340	        return charge;
341	    }
342	
343	    private static BigDecimal figureOf(Claim claim, List<Rate> gradeRates, RoundingMode rounding) {
344	        if (claim.getSettledDue() != null) {
345	            return claim.getSettledDue();
346	        }
347	        return bound(claim) ? claim.getStatedDue() : liveDueOf(claim, gradeRates, rounding);
348	    }
