350	    /** The rate figure of a claim: what is due at the rate its grade has in force on the claim's date, rounded to
351	     * two decimals as the claim rounds (no floor); none when no rate of the grade applies then. */
352	    private static BigDecimal liveDueOf(Claim claim, List<Rate> gradeRates, RoundingMode rounding) {
353	        BigDecimal amount = claim.getAmount();
354	        return Rate.inForce(gradeRates, claim.getDate())
355	                .map(r -> amount.multiply(r.getRate()).divide(BigDecimal.valueOf(100), 2, rounding))
356	                .orElse(null);
357	    }
358	
