364	     * but shows its live figure, and is bound again if it is rejected. */
365	    private static boolean bound(Claim claim) {
366	        return claim.isStated() && claim.getStatus() != ClaimStatus.PENDING;
367	    }
368	
369	    /** Whether a claim is overdue: it is OPEN or PENDING, not deferred, and its due-by is before the sheet's
370	     * today. */
371	    private static boolean overdue(Claim claim, LocalDate today) {
372	        return claim.getStatus().isOpen() && today != null && claim.getDueBy().isBefore(today)
373	                && !claim.deferredOn(today);
374	    }
375	
376	    /** Whether a claim counts toward a period ending on a date: by the status it had at the end of that day, only
377	     * an OPEN, PENDING or SETTLED one does (one added after it does not); one OPEN or PENDING now, dated
378	     * within one of its person's holds or of a person retired on the sheet's today, does not unless it is bound by
379	     * a statement, and one deferred on the sheet's today does not. */
380	    public static boolean countsAt(Claim claim, Person person, LocalDate today, LocalDate end) {
381	        ClaimStatus then = claim.statusAt(end);
382	        if (then == null) {
383	            return false;
384	        }
385	        return (then.isOpen() && (bound(claim) || !claim.getStatus().isOpen() || !leftOut(claim, person, today))
386	                && !claim.deferredOn(today))
387	                || then == ClaimStatus.SETTLED;
388	    }
389	
390	    /** Only OPEN, PENDING and SETTLED claims count toward what is claimed and due; an OPEN or PENDING one dated
391	     * within one of its person's holds, or of a person retired on the sheet's today, does not, unless it is bound
392	     * by a statement, and one deferred on the sheet's today does not. */
393	    public static boolean counts(Claim claim, Person person, LocalDate today) {
394	        return (claim.getStatus().isOpen() && (bound(claim) || !leftOut(claim, person, today))
395	                && !claim.deferredOn(today))
396	                || claim.getStatus() == ClaimStatus.SETTLED;
397	    }
398	
399	    /** Whether an OPEN or PENDING claim not bound by a statement is left out of the live totals: it is dated within
400	     * one of its person's holds, or its person is retired on the sheet's today. */
401	    private static boolean leftOut(Claim claim, Person person, LocalDate today) {
402	        return person.heldOn(claim.getDate()) || person.retiredBy(today);
403	    }
